def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def as_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def safe_list(v):
        return v if isinstance(v, list) else []

    def parse_points(v):
        out = []
        for item in safe_list(v):
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                out.append((item[0], item[1]))
        return out

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""

    me = as_pos(observation.get("self_position"))
    opp = as_pos(observation.get("opponent_position"), me)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    resources = parse_points(observation.get("resources"))
    unclaimed = parse_points(observation.get("unclaimed_cells"))
    opp_terr = parse_points(observation.get("opponent_territory"))
    self_terr = parse_points(observation.get("self_territory"))

